/// Data panduan soket. Posisi (x, y) = pecahan lebar/tinggi gambar assets/tutorial/board_3d.png (0..1).
/// Dihasilkan dari koordinat Gerber PCB1 + render 3D. Tahan lama (long-press) di peta untuk membaca koordinat baru
/// jika gambar render diganti.
class PinDef {
  const PinDef(this.no, this.net, this.fn);
  final String no, net, fn;
}

class UseDef {
  const UseDef(this.name, this.connect, {this.trace = const <String>[], this.warn = const <String>[]});
  final String name;
  final List<String> connect, trace, warn;
}

class SocketDef {
  const SocketDef(this.id, this.title, this.kind, this.where, this.x, this.y, this.pins, {this.dryer, this.washer, this.note});
  final String id, title, kind, where; // kind: mains | hv | low
  final double x, y;
  final List<PinDef> pins;
  final UseDef? dryer, washer;
  final String? note;
}

